head.script:
scwin.onpageload = function () {
	var dataJson = [
		{ "col1": "101", "col2": "201", "col3": "301" },
		{ "col1": "102", "col2": "202", "col3": "302" },
		{ "col1": "103", "col2": "203", "col3": "303" },
		{ "col1": "104", "col2": "204", "col3": "304" },
		{ "col1": "105", "col2": "205", "col3": "305" },
		{ "col1": "106", "col2": "206", "col3": "306" }
	]
	dataList1.setJSON(dataJson);
};

scwin.onpageunload = function () {

};


scwin.trigger1_onclick = function (e) {
	gridView1.setVisibleRowNum(10);

};

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getJq('#trigger1').offset().top > 140;
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('gridView1_body_tbody').children[3].style.display != 'none';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_scrollY_div').scrollTop = 300");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
